python3 -B -I -c "import hashlib,json
h=lambda p:hashlib.sha256(open(p,'rb').read()).hexdigest()
F=['benchmark/cases/dev/library-specialty.json','benchmark/cases/dev/library-icon-tests.json','benchmark/writing/input-pins.json','benchmark/preparation.json','benchmark/challenges/README.md','benchmark/challenges/positive-control-key-0191.json','benchmark/challenges/positive-control-key-0203.json','benchmark/challenges/positive-control-key-0204-icon-tests.json','benchmark/challenges/check_xml_keys.py']
for f in F:print(h(f),f)
p=json.load(open('benchmark/writing/input-pins.json'))
print(list(p))
pi=p.get('protected_inputs_sha256',{})
print('pins',len(pi),'bad',[k for k,v in pi.items() if h(k)!=v])
q=json.load(open('benchmark/preparation.json'))
n=0;bad=[]
def rec(o):
  global n
  if isinstance(o,dict):
    if 'path' in o and 'sha256' in o:
      n+=1
      try:
        if h(o['path'])!=o['sha256']:bad.append(o['path'])
      except Exception as e:bad.append((o['path'],str(e)))
    for v in o.values():rec(v)
  elif isinstance(o,list):
    for v in o:rec(v)
rec(q);print('prep entries',n,'bad',bad)
"
